window.UNITS=[{"g":6,"u":1,"title":"My New School","vi":"Trường mới của em","lessons":[{"type":"v","title":"Types of school & School things – Đồ dùng học tập","words":[{"w":"lower secondary school","vi":"trường cấp 2 (THCS)","ex":"My brother goes to a {lower secondary school} near our house."},{"w":"boarding school","vi":"trường nội trú","ex":"Students live and study at a {boarding school}."},{"w":"international school","vi":"trường quốc tế","ex":"Many foreign students study at the {international school}."},{"w":"pencil case","vi":"hộp bút","ex":"I keep my pens in a {pencil case}."},{"w":"pen","vi":"bút mực","ex":"Can I borrow your {pen}?"},{"w":"notebook","vi":"quyển vở","ex":"Write the new words in your {notebook}."},{"w":"textbook","vi":"sách giáo khoa","ex":"Open your English {textbook} at page 10."},{"w":"pencil sharpener","vi":"cái gọt bút chì","ex":"My pencil is blunt. I need a {pencil sharpener}."},{"w":"compass","vi":"cái com-pa","ex":"We use a {compass} to draw circles."},{"w":"calculator","vi":"cái máy tính (bỏ túi)","ex":"You can't use a {calculator} in the maths test."},{"w":"rubber","vi":"cục tẩy","ex":"Can I use your {rubber}? I made a mistake."},{"w":"eraser","vi":"cục tẩy","ex":"I need an {eraser} to rub out this word."}]},{"type":"v","title":"Subjects & School activities – Các hoạt động ở trường (1/2)","words":[{"w":"maths","vi":"môn toán","ex":"We have {maths} on Monday and Friday."},{"w":"English","vi":"Tiếng Anh","ex":"{English} is my favourite subject."},{"w":"Vietnamese","vi":"Tiếng Việt","ex":"We read poems in our {Vietnamese} lessons."},{"w":"history","vi":"lịch sử","ex":"In {history}, we learn about the past."},{"w":"science","vi":"khoa học","ex":"We do experiments in {science} lessons."},{"w":"music","vi":"âm nhạc","ex":"We sing songs in {music} lessons."},{"w":"art","vi":"mỹ thuật","ex":"We draw pictures in {art} lessons."},{"w":"have new friends","vi":"có bạn mới","ex":"I {have new friends} at my new school."},{"w":"have school lunch","vi":"ăn trưa ở trường","ex":"We {have school lunch} at 11 o'clock."},{"w":"have lessons","vi":"có các tiết học","ex":"We {have lessons} from Monday to Friday."},{"w":"do exercises","vi":"làm bài tập","ex":"We {do exercises} in class."},{"w":"do homework","vi":"làm bài tập về nhà","ex":"I {do homework} every evening."},{"w":"do paintings","vi":"vẽ tranh","ex":"We {do paintings} in the art room."},{"w":"play football","vi":"chơi bóng đá","ex":"The boys {play football} in the playground."},{"w":"play music","vi":"chơi nhạc","ex":"My friends and I {play music} after school."}]},{"type":"v","title":"School activities – Các hoạt động ở trường (2/2)","words":[{"w":"study new words","vi":"học từ mới","ex":"I {study new words} every day."},{"w":"study in the library","vi":"học trong thư viện","ex":"We {study in the library} on Wednesday afternoon."},{"w":"grow flowers","vi":"trồng hoa","ex":"We {grow flowers} in the school garden."},{"w":"swim in the swimming pool","vi":"bơi ở bể bơi","ex":"We {swim in the swimming pool} on Saturdays."},{"w":"help classmates","vi":"giúp đỡ bạn cùng lớp","ex":"Good students {help classmates} with their homework."},{"w":"wear uniforms","vi":"mặc đồng phục","ex":"We {wear uniforms} at school."},{"w":"look smart","vi":"trông lịch sự","ex":"You {look smart} in your new uniform."}]},{"type":"g","title":"Present simple","vi":"Thì hiện tại đơn","notes":["Dùng để nói về thói quen (I get up at 6 a.m. every day.) và sự thật hiển nhiên (The Earth goes around the Sun.).","(+) S + V / V-s / V-es · (–) S + don't / doesn't + V · (?) Do / Does + S + V …?","Chủ ngữ số nhiều (I, you, we, they) dùng V nguyên mẫu / don't / Do; chủ ngữ số ít (he, she, it) dùng V-s/es / doesn't / Does.","Thêm -es sau động từ tận cùng là o, ch, s, x, sh, z: goes, watches, misses, fixes, washes.","Dấu hiệu: always, usually, often, sometimes, rarely, hardly, never (đứng trước động từ thường, sau \"be\"); once a week, twice a week, every day.","Phát âm -s/-es: /s/ sau âm th, p, k, f, t (thanks, stops); /ɪz/ sau x, s, ch, sh, z (watches, washes); /z/ sau các âm còn lại (listens, does)."],"items":[{"t":"gap","q":"They often ___ football after school. (play)","a":["play"]},{"t":"gap","q":"She always ___ TV in the evening. (watch)","a":["watches"]},{"t":"gap","q":"I ___ up early every Sunday. (not get)","a":["don't get","do not get"]},{"t":"gap","q":"Lucy ___ coffee. (not like)","a":["doesn't like","does not like"]},{"t":"gap","q":"___ you enjoy going swimming?","a":["Do"]},{"t":"gap","q":"___ she love collecting coins?","a":["Does"]},{"t":"gap","q":"My father ___ to work by bus. (go)","a":["goes"]},{"t":"gap","q":"The Earth ___ around the Sun. (go)","a":["goes"]},{"t":"gap","q":"We ___ English on Monday. (have)","a":["have"]},{"t":"gap","q":"He ___ his homework after dinner. (do)","a":["does"]},{"t":"mc","q":"My sister ___ her teeth twice a day.","o":["brush","brushs","brushes","brushing"],"a":["brushes"]},{"t":"mc","q":"___ your friends live near the school?","o":["Do","Does","Are","Is"],"a":["Do"]},{"t":"mc","q":"Tom ___ like fish.","o":["don't","doesn't","isn't","aren't"],"a":["doesn't"]},{"t":"mc","q":"I ___ late for school.","o":["never am","am never","never is","is never"],"a":["am never"]},{"t":"mc","q":"She ___ goes to the library on Saturdays.","o":["usually","usual","usualy","use"],"a":["usually"]},{"t":"mc","q":"Which word has the ending pronounced /ɪz/?","o":["watches","stops","listens","plays"],"a":["watches"]},{"t":"mc","q":"Which word has the ending pronounced /s/?","o":["thanks","does","listens","plays"],"a":["thanks"]},{"t":"mc","q":"We go swimming ___ a week.","o":["twice","two","second","double"],"a":["twice"]}]}]},{"g":6,"u":2,"title":"My House","vi":"Ngôi nhà của em","lessons":[{"type":"v","title":"Types of house & Rooms in a house – Các phòng trong nhà","words":[{"w":"villa","vi":"căn biệt thự","ex":"They live in a big {villa} by the sea."},{"w":"flat","vi":"căn hộ","ex":"We live in a small {flat} on the fifth floor."},{"w":"town house","vi":"nhà phố","ex":"My aunt lives in a {town house} in the city centre."},{"w":"country house","vi":"nhà ở quê","ex":"My grandparents have a {country house} with a big garden."},{"w":"stilt house","vi":"nhà sàn","ex":"Many people in the mountains live in a {stilt house}."},{"w":"hall","vi":"sảnh, hành lang","ex":"Leave your shoes in the {hall}."},{"w":"bedroom","vi":"phòng ngủ","ex":"My {bedroom} is small but tidy."},{"w":"living room","vi":"phòng khách","ex":"We watch TV in the {living room}."},{"w":"kitchen","vi":"phòng bếp","ex":"Mum is cooking in the {kitchen}."},{"w":"bathroom","vi":"phòng tắm","ex":"The {bathroom} is next to my bedroom."}]},{"type":"v","title":"Furniture – Nội thất (1/2)","words":[{"w":"television","vi":"ti vi","ex":"There is a big {television} in the living room."},{"w":"computer","vi":"máy tính","ex":"I do my homework on the {computer}."},{"w":"armchair","vi":"ghế bành","ex":"Grandpa is sitting in the {armchair}."},{"w":"lamp","vi":"đèn ngủ, đèn bàn","ex":"There is a {lamp} next to my bed."},{"w":"pillow","vi":"cái gối","ex":"I like a soft {pillow}."},{"w":"picture","vi":"bức tranh","ex":"There is a beautiful {picture} on the wall."},{"w":"clock","vi":"đồng hồ","ex":"The {clock} on the wall says seven o'clock."},{"w":"wardrobe","vi":"tủ quần áo","ex":"I keep my clothes in the {wardrobe}."}]},{"type":"v","title":"Furniture – Nội thất (2/2)","words":[{"w":"dishwasher","vi":"máy rửa bát","ex":"Put the dirty plates in the {dishwasher}."},{"w":"fridge","vi":"tủ lạnh","ex":"Put the milk in the {fridge}."},{"w":"cupboard","vi":"tủ chén bát","ex":"The cups are in the {cupboard}."},{"w":"sink","vi":"bồn rửa","ex":"Wash your hands in the {sink}."},{"w":"cooker","vi":"cái nồi, bếp nấu","ex":"Mum puts the soup on the {cooker}."},{"w":"shower","vi":"vòi sen","ex":"I have a {shower} every morning."},{"w":"chest of drawers","vi":"tủ nhiều ngăn kéo","ex":"My socks are in the {chest of drawers}."}]},{"type":"g","title":"There is / There are","vi":"Có …","notes":["There is + danh từ số ít / không đếm được: There is a lamp and a wardrobe in the bedroom.","There are + danh từ số nhiều: There are two cookers and a cupboard in the kitchen.","Có thể viết lại với \"have/has\": There is a kitchen in my house. = My house has a kitchen."],"items":[{"t":"gap","q":"___ a lamp and a wardrobe in the bedroom.","a":["There is","There's"]},{"t":"gap","q":"___ two cookers in the kitchen.","a":["There are"]},{"t":"gap","q":"There ___ three bedrooms in my house.","a":["are"]},{"t":"gap","q":"There ___ a big fridge in the kitchen.","a":["is"]},{"t":"gap","q":"___ there a sofa in the living room? – Yes, there is.","a":["Is"]},{"t":"gap","q":"There are two beds in my room. = My room ___ two beds.","a":["has"]},{"t":"mc","q":"There ___ some pictures on the wall.","o":["is","are","am","be"],"a":["are"]},{"t":"mc","q":"There ___ a clock in the hall.","o":["is","are","have","has"],"a":["is"]},{"t":"mc","q":"___ there any chairs in the kitchen?","o":["Are","Is","Do","Does"],"a":["Are"]},{"t":"mc","q":"There is a kitchen in my house. = My house ___ a kitchen.","o":["has","have","is","are"],"a":["has"]}]},{"type":"g","title":"Prepositions of place","vi":"Giới từ chỉ vị trí","notes":["in (ở trong): The cat is in the box. · on (ở trên): The book is on the table. · under (ở dưới): Your shoes are under the bed.","next to (bên cạnh): The cat is next to the sofa. · behind (phía sau): The cat is behind the dog. · in front of (phía trước): The dog is in front of the cat.","between … and … (ở giữa): The dog is between the lamp and the armchair."],"items":[{"t":"gap","q":"The cat is ___ the box. (ở trong)","a":["in"]},{"t":"gap","q":"The book is ___ the table. (ở trên)","a":["on"]},{"t":"gap","q":"Your shoes are ___ the bed. (ở dưới)","a":["under"]},{"t":"gap","q":"The dog is ___ the lamp and the armchair. (ở giữa)","a":["between"]},{"t":"gap","q":"The cat is ___ the dog. (phía sau)","a":["behind"]},{"t":"mc","q":"The dog is ___ the cat. (phía trước)","o":["in front of","behind","between","under"],"a":["in front of"]},{"t":"mc","q":"The cat is ___ the sofa. (bên cạnh)","o":["next to","in","on","between"],"a":["next to"]},{"t":"mc","q":"My school is ___ the bank and the post office.","o":["between","next","in front","under"],"a":["between"]}]},{"type":"g","title":"Possessive case","vi":"Sở hữu cách","notes":["Danh từ số ít & tên riêng + 's: This is Jenny's book. The cat's tail is long.","Danh từ số nhiều có -s + ': The students' classroom is big. This is my parents' house."],"items":[{"t":"gap","q":"This is ___ book. (Jenny)","a":["Jenny's"]},{"t":"gap","q":"The ___ tail is long. (cat)","a":["cat's"]},{"t":"gap","q":"This is my ___ house. (parents)","a":["parents'"]},{"t":"gap","q":"The ___ classroom is big and beautiful. (students)","a":["students'"]},{"t":"mc","q":"This is ___ bike.","o":["Nam's","Nams","Nams'","Nam"],"a":["Nam's"]},{"t":"mc","q":"The ___ toys are in the box. (các con chó)","o":["dogs'","dog's","dogs","dogs's"],"a":["dogs'"]},{"t":"mc","q":"My ___ car is red. (bố tôi)","o":["father's","fathers'","fathers","father"],"a":["father's"]}]}]},{"g":6,"u":3,"title":"My Friends","vi":"Bạn bè của em","lessons":[{"type":"v","title":"Hair descriptions – Miêu tả tóc","words":[{"w":"blonde hair","vi":"tóc vàng (sẫm)","ex":"My new friend has long {blonde hair}."},{"w":"fair hair","vi":"tóc vàng hoe (nhạt)","ex":"The baby has {fair hair} and blue eyes."},{"w":"curly hair","vi":"tóc xoăn","ex":"Mai has short {curly hair}."},{"w":"straight hair","vi":"tóc thẳng","ex":"Lan has long black {straight hair}."},{"w":"wavy hair","vi":"tóc gợn sóng","ex":"My mother has beautiful {wavy hair}."},{"w":"What does he look like?","vi":"Cậu ấy trông như thế nào? (hỏi ngoại hình)","ex":"\"{What does he look like?}\" – \"He has short hair and big eyes.\""}]},{"type":"v","title":"Personality adjectives – Tính từ miêu tả tính cách","words":[{"w":"confident","vi":"tự tin","ex":"She is {confident} when she speaks in front of the class."},{"w":"caring","vi":"quan tâm người khác","ex":"My sister is very {caring}; she always looks after me."},{"w":"active","vi":"năng động","ex":"Nam is {active}; he does many activities after school."},{"w":"careful","vi":"cẩn thận","ex":"Be {careful} and check your answers."},{"w":"creative","vi":"sáng tạo","ex":"Minh is {creative}; he always has new ideas."},{"w":"shy","vi":"nhút nhát","ex":"He is {shy}, so he doesn't talk much in class."},{"w":"kind","vi":"tốt bụng","ex":"She is {kind} and always helps her friends."},{"w":"helpful","vi":"hay giúp đỡ","ex":"My classmates are very {helpful}."},{"w":"clever","vi":"thông minh","ex":"Lan is {clever}; she learns quickly and easily."},{"w":"hard-working","vi":"chăm chỉ","ex":"He is {hard-working}; he always does his homework."},{"w":"funny","vi":"hài hước","ex":"My friend is {funny}; he makes people laugh."},{"w":"sporty","vi":"ưa thích thể thao","ex":"Tom is {sporty}; he plays football and tennis."},{"w":"What is she like?","vi":"Cô ấy là người thế nào? (hỏi tính cách)","ex":"\"{What is she like?}\" – \"She is kind and hard-working.\""}]},{"type":"g","title":"Present continuous","vi":"Thì hiện tại tiếp diễn","notes":["(+) S + am/is/are + V-ing · (–) S + am/is/are + not + V-ing · (?) Am/Is/Are + S + V-ing?","Dấu hiệu: now (bây giờ), right now (ngay bây giờ), at the moment / at present (hiện tại), today (hôm nay), dấu ! đầu câu (Look! Listen!).","Ví dụ: I am watching TV now. · Look! They are playing football. · He isn't sleeping now. · Are you doing your homework now? – Yes, I am. / No, I'm not."],"items":[{"t":"gap","q":"I ___ TV now. (watch)","a":["am watching","'m watching"]},{"t":"gap","q":"She ___ at the moment. (cook)","a":["is cooking","'s cooking"]},{"t":"gap","q":"Look! They ___ football. (play)","a":["are playing","'re playing"]},{"t":"gap","q":"I ___ at present. (not study)","a":["am not studying","'m not studying"]},{"t":"gap","q":"He ___ now. (not sleep)","a":["isn't sleeping","is not sleeping"]},{"t":"gap","q":"We ___ at the moment. (not eat)","a":["aren't eating","are not eating"]},{"t":"gap","q":"___ you doing your homework now?","a":["Are"]},{"t":"gap","q":"Is she singing at present? – Yes, she ___.","a":["is"]},{"t":"gap","q":"Listen! The birds ___. (sing)","a":["are singing"]},{"t":"mc","q":"Are they playing games at the moment? – No, they ___.","o":["aren't","isn't","don't","doesn't"],"a":["aren't"]},{"t":"mc","q":"My mother ___ in the kitchen now.","o":["is cooking","cooks","are cooking","cook"],"a":["is cooking"]},{"t":"mc","q":"___ you listening to me?","o":["Are","Do","Is","Does"],"a":["Are"]},{"t":"mc","q":"Which word is a signal for the present continuous?","o":["at the moment","every day","usually","once a week"],"a":["at the moment"]},{"t":"mc","q":"Look! The children ___ in the garden.","o":["are running","run","runs","is running"],"a":["are running"]}]}]},{"g":6,"u":4,"title":"My Neighbourhood","vi":"Khu phố của em","lessons":[{"type":"v","title":"Asking for and giving directions – Hỏi và chỉ đường","words":[{"w":"Let's","vi":"Hãy cùng …","ex":"{Let's} go to the cinema this evening."},{"w":"Shall we","vi":"Chúng ta sẽ … chứ?","ex":"{Shall we} visit the art gallery on Sunday?"},{"w":"Can you show me the way to","vi":"Bạn có thể chỉ cho tôi đường đến …","ex":"Excuse me. {Can you show me the way to} the railway station?"},{"w":"how to get to","vi":"cách để đến …","ex":"Can you tell me {how to get to} the post office?"},{"w":"near","vi":"gần","ex":"My house is {near} the school."},{"w":"far","vi":"xa","ex":"The museum is {far} from here."},{"w":"turn left","vi":"rẽ trái","ex":"{Turn left} at the traffic lights."},{"w":"turn right","vi":"rẽ phải","ex":"{Turn right} and the bank is on your left."},{"w":"go straight","vi":"đi thẳng","ex":"{Go straight} for two blocks."},{"w":"cross the road","vi":"băng qua đường","ex":"Be careful when you {cross the road}."},{"w":"go along the street","vi":"đi dọc theo con đường","ex":"{Go along the street} until you see the park."},{"w":"take the first turning on the right","vi":"rẽ vào ngã rẽ thứ nhất bên phải","ex":"{Take the first turning on the right}, and the café is there."},{"w":"take the second turning on the left","vi":"rẽ vào ngã rẽ thứ hai bên trái","ex":"{Take the second turning on the left} to get to the temple."},{"w":"It's on your right","vi":"Nó ở bên phải của bạn","ex":"Walk for two minutes. {It's on your right}."}]},{"type":"v","title":"Places in a neighbourhood – Các địa điểm thường gặp","words":[{"w":"square","vi":"quảng trường","ex":"There is a fountain in the middle of the {square}."},{"w":"art gallery","vi":"phòng trưng bày mỹ thuật","ex":"We saw many beautiful paintings at the {art gallery}."},{"w":"cathedral","vi":"nhà thờ lớn, thánh đường","ex":"The {cathedral} in the city centre is very old."},{"w":"temple","vi":"ngôi đền, miếu","ex":"Many people visit the {temple} at Tet."},{"w":"railway station","vi":"ga tàu hỏa","ex":"We took a taxi to the {railway station}."},{"w":"live in the suburbs","vi":"sống ở vùng ngoại ô","ex":"I {live in the suburbs} of Ho Chi Minh City."},{"w":"heavy traffic","vi":"tắc nghẽn giao thông","ex":"There is {heavy traffic} in the city centre in the morning."}]},{"type":"g","title":"Comparative adjectives","vi":"So sánh hơn của tính từ","notes":["Tính từ ngắn: adj + -er (+ than): I am taller than you. You are shorter than me. Tính từ 2 âm tiết tận cùng -y cũng là tính từ ngắn: easy → easier, noisy → noisier.","Tính từ dài: more + adj (+ than): This house is more beautiful than my house. The red bike is more expensive than the blue one.","Bất quy tắc: good → better, bad → worse, far → farther/further.","Tận cùng -e chỉ thêm -r (nice → nicer); tính từ 2 âm tiết tận cùng -et, -ow, -er, -le, -ly có thể thêm -er (narrower, quieter, cleverer, friendlier, simpler).","Một nguyên âm + một phụ âm cuối → gấp đôi phụ âm: big → bigger, hot → hotter, fat → fatter, thin → thinner. Không gấp đôi w, x, y: new → newer, slow → slower."],"items":[{"t":"gap","q":"I am ___ than you. (tall)","a":["taller"]},{"t":"gap","q":"You are ___ than me. (short)","a":["shorter"]},{"t":"gap","q":"This exercise is ___ than that one. (easy)","a":["easier"]},{"t":"gap","q":"This house is ___ than my house. (beautiful)","a":["more beautiful"]},{"t":"gap","q":"The red bike is ___ than the blue one. (expensive)","a":["more expensive"]},{"t":"gap","q":"This film is ___ than that one. (good)","a":["better"]},{"t":"gap","q":"The weather today is ___ than yesterday. (bad)","a":["worse"]},{"t":"gap","q":"My school is ___ than yours. (far)","a":["farther","further"]},{"t":"gap","q":"An elephant is ___ than a horse. (big)","a":["bigger"]},{"t":"gap","q":"Summer is ___ than winter. (hot)","a":["hotter"]},{"t":"mc","q":"My new phone is ___ than my old one.","o":["newer","newwer","more new","newest"],"a":["newer"]},{"t":"mc","q":"The countryside is ___ than the city.","o":["quieter","more quiet","quietter","quietest"],"a":["quieter"]},{"t":"mc","q":"This box is ___ than that one.","o":["nicer","nicerer","more nice","nicest"],"a":["nicer"]},{"t":"mc","q":"Mai is ___ than her sister.","o":["more confident","confidenter","most confident","confident"],"a":["more confident"]},{"t":"mc","q":"A car is ___ than a bike.","o":["faster","more fast","fastter","fastest"],"a":["faster"]},{"t":"mc","q":"Which is correct?","o":["thinner","thiner","more thin","thinest"],"a":["thinner"]}]}]},{"g":6,"u":5,"title":"Natural Wonders of Viet Nam","vi":"Kỳ quan thiên nhiên Việt Nam","lessons":[{"type":"v","title":"Places – Địa điểm","words":[{"w":"forest","vi":"khu rừng","ex":"There are many wild animals in the {forest}."},{"w":"island","vi":"hòn đảo","ex":"Phu Quoc is a beautiful {island}."},{"w":"scenery","vi":"phong cảnh","ex":"The {scenery} in Sa Pa is wonderful."},{"w":"landscape","vi":"phong cảnh","ex":"Ha Giang has a beautiful mountain {landscape}."},{"w":"beach","vi":"bãi biển","ex":"We played volleyball on the {beach}."},{"w":"waterfall","vi":"thác nước","ex":"Ban Gioc is a famous {waterfall} in Cao Bang."},{"w":"river","vi":"dòng sông","ex":"The Red {river} flows through Ha Noi."},{"w":"desert","vi":"sa mạc","ex":"It is very hot and dry in the {desert}."},{"w":"mountain","vi":"ngọn núi","ex":"Fansipan is the highest {mountain} in Viet Nam."},{"w":"cave","vi":"hang động","ex":"Son Doong is the biggest {cave} in the world."},{"w":"Ha Long Bay","vi":"Vịnh Hạ Long","ex":"{Ha Long Bay} has thousands of islands."},{"w":"amazing","vi":"tuyệt vời, kinh ngạc","ex":"The view from the top is {amazing}."},{"w":"wonderful","vi":"tuyệt vời","ex":"We had a {wonderful} time in Hoi An."}]},{"type":"v","title":"Travel items & verbs – Đồ dùng khi du lịch và động từ","words":[{"w":"plaster","vi":"băng y tế (băng cá nhân)","ex":"Put a {plaster} on your finger."},{"w":"hurt","vi":"bị đau, bị thương","ex":"Be careful or you will {hurt} yourself."},{"w":"scissors","vi":"cái kéo","ex":"You need {scissors} to cut the paper."},{"w":"sleeping bag","vi":"túi ngủ","ex":"Bring a {sleeping bag} when you go camping."},{"w":"bring","vi":"mang theo","ex":"Don't forget to {bring} your passport."},{"w":"backpack","vi":"ba lô","ex":"I carry my water in a {backpack}."},{"w":"luggage","vi":"hành lý","ex":"We have a lot of {luggage} for the trip."},{"w":"useful","vi":"hữu ích","ex":"A torch is very {useful} at night."},{"w":"compass","vi":"cái la bàn","ex":"Use a {compass} so you don't get lost."},{"w":"get lost","vi":"bị lạc đường","ex":"Take a map or you will {get lost}."},{"w":"overnight","vi":"qua đêm","ex":"We stayed {overnight} in the cave."},{"w":"suncream","vi":"kem chống nắng","ex":"Put on some {suncream} at the beach."},{"w":"pack","vi":"đóng gói, xếp vào túi","ex":"Please {pack} your bag tonight."}]},{"type":"v","title":"Activities and other words – Hoạt động và từ khác","words":[{"w":"leave home","vi":"rời khỏi nhà","ex":"We {leave home} at 6 a.m. for the trip."},{"w":"go for a picnic","vi":"đi dã ngoại","ex":"Let's {go for a picnic} by the lake."},{"w":"make lots of noise","vi":"làm ồn","ex":"Don't {make lots of noise} in the cave."},{"w":"tell the truth","vi":"nói sự thật","ex":"You must always {tell the truth}."},{"w":"visit","vi":"tham quan, đến thăm","ex":"We will {visit} Ha Long Bay next summer."},{"w":"practise","vi":"luyện tập","ex":"I {practise} English every day."},{"w":"natural wonder","vi":"kỳ quan thiên nhiên","ex":"Ha Long Bay is a {natural wonder} of the world."},{"w":"man-made wonder","vi":"kỳ quan nhân tạo","ex":"The Great Wall is a {man-made wonder}."},{"w":"pick flowers","vi":"hái hoa","ex":"Please don't {pick flowers} in the park."}]},{"type":"g","title":"Uncountable nouns","vi":"Danh từ không đếm được","notes":["Chất lỏng, khí: water, milk, tea, oil, coffee, juice, paint, CO2, O2.","Gia vị: sugar, salt, pepper, fish sauce. Chất đặc, sệt: cheese, butter, flour, suncream, ice cream, bread.","Các loại thịt: meat, pork, beef, chicken, fish. Thứ quá nhiều không đếm được: soil, sand, sunlight, rain, snow, hair, time.","Từ khác: furniture, homework, housework, information, ash, wood, luggage, paper, noise.","Danh từ không đếm được không có dạng số nhiều và không đi với a/an: some water, a lot of information."],"items":[{"t":"mc","q":"Which noun is UNCOUNTABLE?","o":["water","apple","book","chair"],"a":["water"]},{"t":"mc","q":"Which noun is UNCOUNTABLE?","o":["furniture","table","lamp","bed"],"a":["furniture"]},{"t":"mc","q":"Which noun is UNCOUNTABLE?","o":["information","question","answer","idea"],"a":["information"]},{"t":"mc","q":"Which noun is COUNTABLE?","o":["egg","bread","rice","sugar"],"a":["egg"]},{"t":"mc","q":"Which is correct?","o":["some luggage","a luggage","two luggages","luggages"],"a":["some luggage"]},{"t":"mc","q":"I have a lot of ___ today.","o":["homework","homeworks","a homework","homeworkes"],"a":["homework"]},{"t":"mc","q":"Can you give me some ___?","o":["information","informations","an information","a information"],"a":["information"]},{"t":"mc","q":"We need some ___ to make a cake.","o":["flour","flours","a flour","an flour"],"a":["flour"]}]},{"type":"g","title":"Quantifiers & must / mustn't","vi":"Từ định lượng và must","notes":["some: câu khẳng định và lời mời (Would you like some tea?), dùng với cả 2 loại danh từ. any: câu phủ định và câu hỏi (I don't have any dogs. Do you have any milk?).","many / a few + danh từ đếm được số nhiều (many books, a few friends); much / a little + danh từ không đếm được (much money, a little milk).","must + V: phải làm (điều rất quan trọng): You must do your homework. mustn't + V: cấm làm: You mustn't run in the library."],"items":[{"t":"gap","q":"I have ___ cookies. (một vài, câu khẳng định)","a":["some"]},{"t":"gap","q":"Would you like ___ tea?","a":["some"]},{"t":"gap","q":"I don't have ___ dogs.","a":["any"]},{"t":"gap","q":"Do you have ___ milk?","a":["any"]},{"t":"gap","q":"There are ___ books on my desk. (nhiều)","a":["many"]},{"t":"gap","q":"I don't have ___ money. (nhiều)","a":["much"]},{"t":"gap","q":"I have ___ friends. (một vài)","a":["a few"]},{"t":"gap","q":"There is ___ milk in the fridge. (một ít)","a":["a little"]},{"t":"gap","q":"You ___ wear a helmet when riding a motorbike. (phải)","a":["must"]},{"t":"gap","q":"You ___ run in the library. (cấm)","a":["mustn't","must not"]},{"t":"mc","q":"How ___ water do you drink every day?","o":["much","many","a few","any"],"a":["much"]},{"t":"mc","q":"You ___ touch the pictures in the museum.","o":["mustn't","must","have","don't"],"a":["mustn't"]},{"t":"mc","q":"There aren't ___ students in the classroom.","o":["any","some","much","a little"],"a":["any"]},{"t":"mc","q":"She has ___ good friends at school.","o":["a few","a little","much","any"],"a":["a few"]},{"t":"mc","q":"You ___ do your homework before class.","o":["must","mustn't","aren't","don't"],"a":["must"]}]}]},{"g":6,"u":6,"title":"Our Tet Holiday","vi":"Tết của chúng ta","lessons":[{"type":"v","title":"Activities at Tet – Hoạt động ngày Tết (1/2)","words":[{"w":"celebrate Tet","vi":"tổ chức mừng Tết","ex":"Vietnamese people {celebrate Tet} in January or February."},{"w":"put lucky money into red envelopes","vi":"bỏ tiền lì xì vào phong bao đỏ","ex":"My parents {put lucky money into red envelopes}."},{"w":"give lucky money","vi":"tặng tiền lì xì","ex":"Grandparents {give lucky money} to children."},{"w":"get lucky money","vi":"nhận tiền lì xì","ex":"Children love to {get lucky money} at Tet."},{"w":"buy peach flowers","vi":"mua hoa đào","ex":"We {buy peach flowers} to decorate the house."},{"w":"make banh chung and banh tet","vi":"làm bánh chưng và bánh tét","ex":"My family {make banh chung and banh tet} before Tet."},{"w":"hold a family gathering","vi":"tổ chức họp mặt gia đình","ex":"We {hold a family gathering} on the first day of Tet."},{"w":"make a wish","vi":"ước nguyện","ex":"Close your eyes and {make a wish}."},{"w":"say wishes","vi":"nói lời chúc","ex":"Children {say wishes} to their grandparents."}]},{"type":"v","title":"Activities at Tet – Hoạt động ngày Tết (2/2)","words":[{"w":"visit relatives","vi":"thăm họ hàng","ex":"We {visit relatives} on the second day of Tet."},{"w":"help with housework","vi":"giúp đỡ việc nhà","ex":"I {help with housework} before Tet."},{"w":"clean the furniture","vi":"lau chùi nội thất","ex":"We {clean the furniture} to welcome the New Year."},{"w":"decorate the house","vi":"trang trí nhà cửa","ex":"We {decorate the house} with flowers and lights."},{"w":"do the shopping","vi":"đi mua sắm","ex":"Mum and I {do the shopping} at the market."},{"w":"cook special food","vi":"nấu món ăn đặc biệt","ex":"My grandmother {cooks special food} at Tet."},{"w":"watch fireworks","vi":"xem pháo hoa","ex":"We {watch fireworks} at midnight."},{"w":"visit a pagoda","vi":"viếng chùa","ex":"Many people {visit a pagoda} at the start of the year."}]},{"type":"v","title":"Other words – Từ khác","words":[{"w":"knock before you enter","vi":"gõ cửa trước khi vào","ex":"You should {knock before you enter} the room."},{"w":"behave well","vi":"cư xử ngoan","ex":"Children should {behave well} at Tet."},{"w":"eat sweets","vi":"ăn bánh kẹo ngọt","ex":"Don't {eat sweets} before dinner."},{"w":"break things","vi":"làm vỡ đồ","ex":"We shouldn't {break things} at Tet."},{"w":"fight","vi":"đánh nhau","ex":"Brothers shouldn't {fight}."},{"w":"take things from a shelf","vi":"lấy đồ từ kệ","ex":"Ask before you {take things from a shelf}."},{"w":"make a lot of noise","vi":"làm ồn ào","ex":"Don't {make a lot of noise} at night."}]},{"type":"g","title":"Should / shouldn't","vi":"Đưa ra lời khuyên","notes":["should / shouldn't + V (nguyên mẫu): dùng để đưa ra lời khuyên.","You should make a wish at Tet. · We should plant more trees. · You should behave well.","You shouldn't eat lots of sweets. · We shouldn't break things at Tet. · Tom and Jack shouldn't fight."],"items":[{"t":"gap","q":"You ___ make a wish at Tet. (nên)","a":["should"]},{"t":"gap","q":"You ___ eat lots of sweets. (không nên)","a":["shouldn't","should not"]},{"t":"gap","q":"We ___ plant more trees. (nên)","a":["should"]},{"t":"gap","q":"Tom and Jack ___ fight. (không nên)","a":["shouldn't","should not"]},{"t":"gap","q":"You should ___ well at Tet. (behave)","a":["behave"]},{"t":"mc","q":"You have a headache. You ___ go to bed early.","o":["should","shouldn't","mustn't","don't"],"a":["should"]},{"t":"mc","q":"Children ___ break things at Tet.","o":["shouldn't","should","do","must"],"a":["shouldn't"]},{"t":"mc","q":"We should ___ our grandparents at Tet.","o":["visit","visits","visiting","to visit"],"a":["visit"]},{"t":"mc","q":"It's cold. You ___ wear a coat.","o":["should","shouldn't","aren't","don't"],"a":["should"]},{"t":"mc","q":"You ___ make a lot of noise at night.","o":["shouldn't","should","are","do"],"a":["shouldn't"]}]}]},{"g":6,"u":7,"title":"Television","vi":"Truyền hình","lessons":[{"type":"v","title":"TV programmes – Các chương trình truyền hình (1/2)","words":[{"w":"popular channel","vi":"kênh phổ biến, nổi tiếng","ex":"VTV3 is a {popular channel} in Viet Nam."},{"w":"talent show","vi":"chương trình tài năng","ex":"My sister sang in a {talent show}."},{"w":"science programme","vi":"chương trình khoa học","ex":"I learn a lot from this {science programme}."},{"w":"game show","vi":"chương trình trò chơi","ex":"My dad likes watching {game show}s on Saturday."},{"w":"TV programme","vi":"chương trình truyền hình","ex":"What's your favourite {TV programme}?"},{"w":"animated film","vi":"phim hoạt hình","ex":"Frozen is a famous {animated film}."},{"w":"cartoon","vi":"phim hoạt hình","ex":"Doraemon is my favourite {cartoon}."},{"w":"comedy","vi":"hài kịch","ex":"We laughed a lot at the {comedy}."},{"w":"educational programme","vi":"chương trình giáo dục","ex":"This {educational programme} teaches children English."}]},{"type":"v","title":"TV programmes – Các chương trình truyền hình (2/2)","words":[{"w":"sports programme","vi":"chương trình thể thao","ex":"My brother never misses the {sports programme}."},{"w":"animal programme","vi":"chương trình về động vật","ex":"I watch an {animal programme} about elephants."},{"w":"TV series","vi":"phim truyền hình nhiều tập","ex":"This {TV series} has 40 episodes."},{"w":"boring","vi":"chán","ex":"The film was so {boring} that I fell asleep."},{"w":"interesting","vi":"thú vị","ex":"The science programme is very {interesting}."},{"w":"cute character","vi":"nhân vật đáng yêu","ex":"Pikachu is a {cute character}."},{"w":"live","vi":"trực tiếp","ex":"The football match is shown {live} on TV."},{"w":"attract","vi":"thu hút","ex":"Cartoons {attract} a lot of children."}]},{"type":"g","title":"Wh-questions & Conjunctions","vi":"Từ để hỏi và liên từ","notes":["What (cái gì): What do you watch? · Where (ở đâu): Where do you play football? · When (khi nào): When do you play football?","Why (vì sao) → Because …: Why do you like Doraemon? · Who (ai): Who do you like best in Doraemon?","How many (bao nhiêu – đếm được): How many cartoons do you watch every week? · How often (mấy lần): How often do you watch TV?","but (nhưng – đối lập): I like cartoons, but my brother likes game shows. · so (vì vậy – kết quả): I like sport, so I play football twice a week. · and (và – bổ sung): I enjoy animal programmes, and my sister likes them, too."],"items":[{"t":"mc","q":"___ do you watch TV? – In the evening.","o":["When","Where","Who","What"],"a":["When"]},{"t":"mc","q":"___ do you play football? – In the park.","o":["Where","When","Why","How many"],"a":["Where"]},{"t":"mc","q":"___ do you like Doraemon? – Because he is funny.","o":["Why","What","Who","Where"],"a":["Why"]},{"t":"mc","q":"___ do you like best in Doraemon? – Nobita.","o":["Who","What","When","How often"],"a":["Who"]},{"t":"mc","q":"___ cartoons do you watch every week? – Three.","o":["How many","How often","How much","What"],"a":["How many"]},{"t":"mc","q":"___ do you watch TV? – Twice a week.","o":["How often","How many","When","What"],"a":["How often"]},{"t":"mc","q":"___ is your favourite TV programme?","o":["What","Who","Where","Why"],"a":["What"]},{"t":"mc","q":"I like cartoons, ___ my brother likes game shows.","o":["but","so","and","because"],"a":["but"]},{"t":"mc","q":"It was raining, ___ we stayed at home.","o":["so","but","and","or"],"a":["so"]},{"t":"mc","q":"I enjoy animal programmes, ___ my sister likes them, too.","o":["and","but","so","because"],"a":["and"]},{"t":"gap","q":"___ do you live? – I live in Ha Noi.","a":["Where"]},{"t":"gap","q":"___ often do you go swimming? – Once a week.","a":["How"]},{"t":"gap","q":"The film is long, ___ it is very interesting. (nhưng)","a":["but"]},{"t":"gap","q":"I was tired, ___ I went to bed early. (vì vậy)","a":["so"]}]}]},{"g":6,"u":8,"title":"Sports and Games","vi":"Thể thao và trò chơi","lessons":[{"type":"v","title":"Sports – Các môn thể thao","words":[{"w":"do exercise","vi":"tập thể dục","ex":"I {do exercise} every morning."},{"w":"do karate","vi":"tập karate","ex":"My brother {does karate} twice a week."},{"w":"do aerobics","vi":"tập aerobic","ex":"My mum {does aerobics} at the gym."},{"w":"do yoga","vi":"tập yoga","ex":"She {does yoga} to relax."},{"w":"play board games","vi":"chơi trò chơi bàn cờ","ex":"We {play board games} on rainy days."},{"w":"play chess","vi":"chơi cờ vua","ex":"My grandpa likes to {play chess}."},{"w":"play table tennis","vi":"chơi bóng bàn","ex":"We {play table tennis} after school."},{"w":"play volleyball","vi":"chơi bóng chuyền","ex":"The girls {play volleyball} on the beach."},{"w":"play badminton","vi":"chơi cầu lông","ex":"I {play badminton} with my dad."},{"w":"go swimming","vi":"đi bơi","ex":"We {go swimming} in summer."},{"w":"go fishing","vi":"đi câu cá","ex":"My uncle often {goes fishing} at the weekend."},{"w":"go boating","vi":"đi chèo thuyền","ex":"They {go boating} on the lake."},{"w":"go cycling","vi":"đi xe đạp","ex":"Let's {go cycling} in the park."}]},{"type":"v","title":"Other words – Từ khác","words":[{"w":"win a competition","vi":"thắng một cuộc thi","ex":"Our team {won a competition} last year."},{"w":"become a champion","vi":"trở thành nhà vô địch","ex":"He wants to {become a champion}."},{"w":"send congratulations","vi":"gửi lời chúc mừng","ex":"We {sent congratulations} to the winner."},{"w":"sporty","vi":"khỏe khoắn, thích thể thao","ex":"My brother is very {sporty}."},{"w":"take place","vi":"diễn ra","ex":"The match will {take place} on Sunday."},{"w":"park","vi":"đỗ xe","ex":"You can't {park} here."},{"w":"tidy up","vi":"dọn dẹp","ex":"{Tidy up} your room, please."},{"w":"use the lift","vi":"sử dụng thang máy","ex":"Don't {use the lift} when there is a fire."},{"w":"equipment","vi":"thiết bị, dụng cụ","ex":"The gym has modern {equipment}."},{"w":"run a marathon","vi":"chạy một cuộc đua marathon","ex":"My dad wants to {run a marathon}."},{"w":"goggles","vi":"kính bơi","ex":"Wear {goggles} when you go swimming."},{"w":"racket","vi":"cái vợt","ex":"I need a new tennis {racket}."}]},{"type":"g","title":"Imperatives","vi":"Câu mệnh lệnh","notes":["Khẳng định: V (nguyên mẫu) …: Open the door, please! Tidy up your room.","Phủ định: Don't + V …: Don't talk in class! Don't use the lift when there is a fire.","do + môn chơi 1 người (do exercise, do karate, do yoga); play + môn có ≥ 2 người (play chess, play volleyball); go + V-ing (go swimming, go fishing, go cycling)."],"items":[{"t":"gap","q":"___ the door, please! (mở)","a":["Open"]},{"t":"gap","q":"___ talk in class! (không được)","a":["Don't","Do not"]},{"t":"gap","q":"___ up your room. (dọn)","a":["Tidy"]},{"t":"gap","q":"___ use the lift when there is a fire.","a":["Don't","Do not"]},{"t":"gap","q":"My father often goes ___ at the weekend. (fish)","a":["fishing"]},{"t":"gap","q":"Let's ___ volleyball on the beach.","a":["play"]},{"t":"gap","q":"She ___ yoga every morning.","a":["does"]},{"t":"mc","q":"___ quiet, please!","o":["Be","Are","Is","Being"],"a":["Be"]},{"t":"mc","q":"___ run in the classroom!","o":["Don't","Not","No","Doesn't"],"a":["Don't"]},{"t":"mc","q":"I ___ karate twice a week.","o":["do","play","go","make"],"a":["do"]},{"t":"mc","q":"We ___ badminton after school.","o":["play","do","go","make"],"a":["play"]},{"t":"mc","q":"They ___ cycling in the park.","o":["go","play","do","make"],"a":["go"]},{"t":"mc","q":"___ your hands before meals.","o":["Wash","Washing","Washes","To wash"],"a":["Wash"]}]},{"type":"g","title":"Past simple","vi":"Thì quá khứ đơn","notes":["Dùng diễn tả hành động đã xảy ra và kết thúc trong quá khứ: I watched TV last night. He went to school yesterday.","(+) S + V2/V-ed · (–) S + didn't + V · (?) Did + S + V …?","Dấu hiệu: yesterday, ago, last (night/week/year), in the past, in + năm quá khứ (in 2025).","Phát âm -ed: /t/ sau s, sh, ch, k, p, f (cooked, stopped, watched); /ɪd/ sau t, d (wanted, visited, needed); /d/ sau các âm còn lại (played, opened, studied)."],"items":[{"t":"gap","q":"I ___ football yesterday. (play)","a":["played"]},{"t":"gap","q":"They ___ their homework last night. (do)","a":["did"]},{"t":"gap","q":"We ___ any new books last Sunday. (not buy)","a":["didn't buy","did not buy"]},{"t":"gap","q":"___ you visit the museum in 2025?","a":["Did"]},{"t":"gap","q":"He ___ to school by bike yesterday. (go)","a":["went"]},{"t":"gap","q":"She ___ a letter to her friend last week. (write)","a":["wrote"]},{"t":"gap","q":"I ___ my grandparents two days ago. (visit)","a":["visited"]},{"t":"gap","q":"We ___ a lot of photos on our trip. (take)","a":["took"]},{"t":"mc","q":"I ___ a new bike last month.","o":["bought","buyed","buy","buys"],"a":["bought"]},{"t":"mc","q":"___ she watch TV last night?","o":["Did","Does","Do","Was"],"a":["Did"]},{"t":"mc","q":"They didn't ___ to the party.","o":["come","came","comes","coming"],"a":["come"]},{"t":"mc","q":"Which word has -ed pronounced /ɪd/?","o":["wanted","played","cooked","opened"],"a":["wanted"]},{"t":"mc","q":"Which word has -ed pronounced /t/?","o":["watched","visited","needed","studied"],"a":["watched"]},{"t":"mc","q":"We met our teacher ___.","o":["yesterday","tomorrow","now","every day"],"a":["yesterday"]}]},{"type":"v","title":"Irregular verbs – Động từ bất quy tắc (dạng quá khứ) (1/3)","words":[{"w":"went","vi":"đi (quá khứ của go)","ex":"We {went} to the zoo last Sunday."},{"w":"grew","vi":"trồng, lớn lên (quá khứ của grow)","ex":"My grandma {grew} vegetables in her garden."},{"w":"gave","vi":"đưa cho, tặng (quá khứ của give)","ex":"She {gave} me a nice present."},{"w":"did","vi":"làm (quá khứ của do)","ex":"I {did} my homework last night."},{"w":"had","vi":"có (quá khứ của have)","ex":"We {had} a great time at the beach."},{"w":"ate","vi":"ăn (quá khứ của eat)","ex":"He {ate} two bowls of pho."},{"w":"taught","vi":"dạy (quá khứ của teach)","ex":"Mr Nam {taught} us maths last year."},{"w":"took","vi":"lấy, mang đi (quá khứ của take)","ex":"She {took} a lot of photos."},{"w":"told","vi":"kể, nói (quá khứ của tell)","ex":"Grandpa {told} us a funny story."},{"w":"began","vi":"bắt đầu (quá khứ của begin)","ex":"The film {began} at 8 p.m."},{"w":"became","vi":"trở thành (quá khứ của become)","ex":"He {became} a champion in 2024."}]},{"type":"v","title":"Irregular verbs – Động từ bất quy tắc (dạng quá khứ) (2/3)","words":[{"w":"bought","vi":"mua (quá khứ của buy)","ex":"I {bought} a new bag yesterday."},{"w":"beat","vi":"đánh bại (quá khứ của beat)","ex":"Our team {beat} their team 3–1."},{"w":"cut","vi":"cắt (quá khứ của cut)","ex":"Mum {cut} the cake into eight pieces."},{"w":"drank","vi":"uống (quá khứ của drink)","ex":"I {drank} a glass of milk."},{"w":"put","vi":"đặt, để (quá khứ của put)","ex":"He {put} the book on the table."},{"w":"won","vi":"chiến thắng (quá khứ của win)","ex":"Viet Nam {won} the match."},{"w":"knew","vi":"biết (quá khứ của know)","ex":"I {knew} the answer."},{"w":"read","vi":"đọc (quá khứ của read)","ex":"I {read} a good book last week."},{"w":"saw","vi":"nhìn thấy (quá khứ của see)","ex":"We {saw} a big elephant at the zoo."},{"w":"sent","vi":"gửi đi (quá khứ của send)","ex":"She {sent} me an email."},{"w":"sold","vi":"bán (quá khứ của sell)","ex":"They {sold} their old car."}]},{"type":"v","title":"Irregular verbs – Động từ bất quy tắc (dạng quá khứ) (3/3)","words":[{"w":"swam","vi":"bơi (quá khứ của swim)","ex":"We {swam} in the sea."},{"w":"spoke","vi":"nói (quá khứ của speak)","ex":"He {spoke} English very well."},{"w":"made","vi":"làm, tạo ra (quá khứ của make)","ex":"Mum {made} a cake for me."},{"w":"wrote","vi":"viết (quá khứ của write)","ex":"I {wrote} a postcard to my friend."},{"w":"wore","vi":"mặc, đội (quá khứ của wear)","ex":"She {wore} a red dress to the party."},{"w":"rode","vi":"đạp xe, cưỡi (quá khứ của ride)","ex":"He {rode} his bike to school."},{"w":"held","vi":"cầm, nắm, tổ chức (quá khứ của hold)","ex":"They {held} a party last night."},{"w":"heard","vi":"nghe (quá khứ của hear)","ex":"I {heard} a strange noise."},{"w":"met","vi":"gặp gỡ (quá khứ của meet)","ex":"I {met} my best friend at the park."}]}]},{"g":6,"u":9,"title":"Cities of the World","vi":"Các thành phố trên thế giới","lessons":[{"type":"v","title":"Places – Địa điểm","words":[{"w":"famous landmark","vi":"địa danh nổi tiếng","ex":"The Eiffel Tower is a {famous landmark}."},{"w":"Eiffel Tower","vi":"tháp Eiffel (Paris, Pháp)","ex":"We took photos in front of the {Eiffel Tower}."},{"w":"Sydney Opera House","vi":"nhà hát Opera Sydney (Úc)","ex":"The {Sydney Opera House} looks like big shells."},{"w":"Big Ben","vi":"tháp đồng hồ Big Ben (London, Anh)","ex":"{Big Ben} is a famous clock tower in London."},{"w":"Merlion","vi":"tượng sư tử biển (Singapore)","ex":"The {Merlion} is a symbol of Singapore."},{"w":"building","vi":"tòa nhà","ex":"It is the tallest {building} in the city."},{"w":"stall","vi":"gian hàng","ex":"She sells fruit at a small {stall}."},{"w":"street food","vi":"món ăn đường phố","ex":"Ha Noi is famous for its {street food}."},{"w":"night market","vi":"chợ đêm","ex":"We bought souvenirs at the {night market}."},{"w":"river bank","vi":"bờ sông","ex":"We walked along the {river bank}."},{"w":"floating market","vi":"chợ nổi","ex":"Cai Rang is a famous {floating market}."},{"w":"royal palace","vi":"cung điện hoàng gia","ex":"The king lived in the {royal palace}."}]},{"type":"v","title":"Adjectives and other words – Tính từ và từ khác","words":[{"w":"exciting","vi":"thú vị","ex":"Bangkok is an {exciting} city."},{"w":"famous","vi":"nổi tiếng","ex":"Paris is {famous} for the Eiffel Tower."},{"w":"old","vi":"cũ, cổ","ex":"Hoi An is a very {old} town."},{"w":"quiet","vi":"yên tĩnh","ex":"The village is {quiet} at night."},{"w":"crowded","vi":"đông đúc","ex":"The market is always {crowded} at weekends."},{"w":"rainy","vi":"có mưa, mưa nhiều","ex":"London is often {rainy}."},{"w":"sunny","vi":"có nắng","ex":"It's {sunny} today, so let's go to the beach."},{"w":"friendly","vi":"thân thiện","ex":"The people in Hue are very {friendly}."},{"w":"helpful","vi":"sẵn sàng giúp đỡ","ex":"The tour guide was very {helpful}."},{"w":"cute","vi":"đáng yêu","ex":"What a {cute} little dog!"},{"w":"map","vi":"bản đồ","ex":"Look at the {map} to find the way."},{"w":"postcard","vi":"bưu thiếp","ex":"I sent my friend a {postcard} from Paris."},{"w":"shell","vi":"vỏ sò","ex":"We collected {shell}s on the beach."},{"w":"rent","vi":"thuê, mướn","ex":"We {rent} bikes to go around the city."}]},{"type":"g","title":"Possessive adjectives & pronouns","vi":"Tính từ sở hữu & đại từ sở hữu","notes":["Tính từ sở hữu (my, your, his, her, its, our, their) đứng trước danh từ: This is my book. Her father is a doctor.","Đại từ sở hữu (mine, yours, his, hers, its, ours, theirs) đứng một mình, không có danh từ theo sau: This book is mine. That bike is hers.","Your pen is blue. His is red. (His = his pen)"],"items":[{"t":"gap","q":"This is ___ book. (của tôi – tính từ sở hữu)","a":["my"]},{"t":"gap","q":"This book is ___. (của tôi – đại từ sở hữu)","a":["mine"]},{"t":"gap","q":"That bike is ___. (của cô ấy)","a":["hers"]},{"t":"gap","q":"___ father is a doctor. (của cô ấy)","a":["Her"]},{"t":"gap","q":"Your pen is blue. ___ is red. (của anh ấy)","a":["His"]},{"t":"gap","q":"This is our house. It's ___.","a":["ours"]},{"t":"gap","q":"These are their toys. They're ___.","a":["theirs"]},{"t":"mc","q":"Is this pencil ___? – Yes, it's mine.","o":["yours","your","you","you're"],"a":["yours"]},{"t":"mc","q":"The dog is wagging ___ tail.","o":["its","it's","it","his"],"a":["its"]},{"t":"mc","q":"That isn't my bag. Mine is black. – Is it ___?","o":["hers","her","she","she's"],"a":["hers"]},{"t":"mc","q":"We love ___ city very much.","o":["our","ours","we","us"],"a":["our"]},{"t":"mc","q":"Their house is big, but ___ is small.","o":["ours","our","we","us"],"a":["ours"]}]}]},{"g":6,"u":10,"title":"Our Houses in the Future","vi":"Ngôi nhà của chúng ta trong tương lai","lessons":[{"type":"v","title":"House appliances – Thiết bị trong nhà","words":[{"w":"electric cooker","vi":"nồi cơm điện","ex":"We cook rice in an {electric cooker}."},{"w":"cook rice","vi":"nấu cơm","ex":"My mum {cooks rice} for dinner."},{"w":"electric fan","vi":"quạt điện","ex":"Turn on the {electric fan}. It's hot."},{"w":"washing machine","vi":"máy giặt","ex":"The {washing machine} can wash and dry clothes."},{"w":"wash and dry clothes","vi":"giặt và sấy khô quần áo","ex":"Robots will {wash and dry clothes} for us."},{"w":"dishwasher","vi":"máy rửa chén","ex":"The {dishwasher} washes and dries the dishes."},{"w":"fridge","vi":"tủ lạnh","ex":"The {fridge} keeps food fresh."},{"w":"keep food fresh","vi":"giữ thức ăn tươi","ex":"A fridge helps {keep food fresh}."},{"w":"smart clock","vi":"đồng hồ thông minh","ex":"My {smart clock} wakes me up at 6 a.m."},{"w":"wireless TV","vi":"TV không dây","ex":"With a {wireless TV}, we can send and receive emails."},{"w":"receive and send emails","vi":"nhận và gửi email","ex":"I can {receive and send emails} on my phone."},{"w":"laptop","vi":"máy tính xách tay","ex":"I do my homework on my {laptop}."}]},{"type":"v","title":"Daily routines – Công việc hằng ngày","words":[{"w":"clean the floor","vi":"lau sàn nhà","ex":"A robot will {clean the floor}."},{"w":"cook meals","vi":"nấu ăn","ex":"My dad {cooks meals} at weekends."},{"w":"feed the dogs and cats","vi":"cho chó mèo ăn","ex":"I {feed the dogs and cats} every morning."},{"w":"buy food from the supermarket","vi":"mua thức ăn ở siêu thị","ex":"We {buy food from the supermarket} on Sundays."},{"w":"water the flowers","vi":"tưới hoa","ex":"Don't forget to {water the flowers}."},{"w":"contact my friends","vi":"liên lạc bạn bè","ex":"I {contact my friends} by phone."},{"w":"look after the house","vi":"trông coi nhà cửa","ex":"A robot will {look after the house} when we are away."},{"w":"take care of children","vi":"chăm sóc trẻ em","ex":"Grandma helps {take care of children}."},{"w":"iron the clothes","vi":"ủi quần áo","ex":"Mum {irons the clothes} on Sunday."},{"w":"do the housework","vi":"làm việc nhà","ex":"Robots will {do the housework} in the future."}]},{"type":"v","title":"Places – Cụm từ chỉ vị trí","words":[{"w":"in the ocean","vi":"ở trong đại dương","ex":"My future house will be {in the ocean}."},{"w":"by the sea","vi":"ở gần biển","ex":"They live in a villa {by the sea}."},{"w":"in the city","vi":"ở trong thành phố","ex":"It's noisy {in the city}."},{"w":"in the countryside","vi":"ở vùng nông thôn","ex":"The air is fresh {in the countryside}."},{"w":"in the town","vi":"ở trong thị trấn","ex":"There is a small market {in the town}."},{"w":"in the mountains","vi":"ở trong núi","ex":"We stayed in a hut {in the mountains}."},{"w":"in the sky","vi":"ở trên bầu trời","ex":"Birds fly {in the sky}."},{"w":"on the Moon","vi":"ở trên mặt trăng","ex":"People might live {on the Moon} one day."}]},{"type":"g","title":"Future simple & might","vi":"Tương lai đơn và might","notes":["Will: (+) S + will + V · (–) S + will not (won't) + V · (?) Will + S + V? — I will do my homework tonight. She won't go to class tomorrow.","Dấu hiệu: tomorrow, next (week/year), in the future, in + năm tương lai (in 2050), one day / someday.","Might (có thể – không chắc chắn): (+) S + might + V · (–) S + might not + V · (?) Might + S + V? — I might watch a movie later. He might not visit you tomorrow."],"items":[{"t":"gap","q":"I ___ my homework tonight. (do)","a":["will do","'ll do"]},{"t":"gap","q":"She ___ to class tomorrow. (not go)","a":["won't go","will not go"]},{"t":"gap","q":"___ she travel to Da Lat tomorrow?","a":["Will"]},{"t":"gap","q":"I ___ a movie later. (watch – có thể, không chắc chắn)","a":["might watch"]},{"t":"gap","q":"He ___ you tomorrow. (not visit – có thể)","a":["might not visit"]},{"t":"gap","q":"In 2050, people ___ on the Moon. (live)","a":["will live"]},{"t":"mc","q":"Our house ___ a robot in the future.","o":["will have","has","had","having"],"a":["will have"]},{"t":"mc","q":"It ___ rain tomorrow. I'm not sure.","o":["might","will","must","should"],"a":["might"]},{"t":"mc","q":"___ you come to my party next Sunday?","o":["Will","Do","Did","Are"],"a":["Will"]},{"t":"mc","q":"Robots ___ do the housework in the future.","o":["will","did","were","are doing"],"a":["will"]},{"t":"mc","q":"Which word is a signal for the future simple?","o":["next year","yesterday","now","last week"],"a":["next year"]},{"t":"mc","q":"I ___ go out tonight because I am tired.","o":["won't","don't","didn't","wasn't"],"a":["won't"]}]}]},{"g":6,"u":11,"title":"Our Greener World","vi":"Thế giới xanh hơn của chúng ta","lessons":[{"type":"v","title":"Green activities – Hoạt động xanh","words":[{"w":"greener world","vi":"thế giới xanh hơn","ex":"Let's work together for a {greener world}."},{"w":"go on a picnic","vi":"đi dã ngoại","ex":"We {go on a picnic} in the park every spring."},{"w":"help the environment","vi":"giúp môi trường","ex":"Recycling can {help the environment}."},{"w":"plant trees and flowers","vi":"trồng cây và hoa","ex":"Our class will {plant trees and flowers} in the schoolyard."},{"w":"pick up rubbish","vi":"nhặt rác","ex":"We {pick up rubbish} on the beach."},{"w":"use reusable bags when shopping","vi":"dùng túi tái sử dụng khi mua sắm","ex":"We should {use reusable bags when shopping}."},{"w":"reduce","vi":"giảm bớt","ex":"We should {reduce} the amount of plastic we use."},{"w":"reuse","vi":"tái sử dụng","ex":"You can {reuse} glass bottles."},{"w":"recycle","vi":"tái chế","ex":"We {recycle} paper and plastic."},{"w":"cycle","vi":"đi xe đạp","ex":"I {cycle} to school every day."},{"w":"walk","vi":"đi bộ","ex":"Let's {walk} instead of going by car."}]},{"type":"v","title":"Things and actions – Đồ vật và hành động","words":[{"w":"recycling bin","vi":"thùng tái chế","ex":"Put the cans in the {recycling bin}."},{"w":"plastic bag","vi":"túi nhựa","ex":"Don't use too many {plastic bag}s."},{"w":"plastic bottle","vi":"chai nhựa","ex":"I reuse my {plastic bottle}."},{"w":"glass","vi":"thủy tinh","ex":"These jars are made of {glass}."},{"w":"paper","vi":"giấy","ex":"We recycle old {paper}."},{"w":"clothes","vi":"quần áo","ex":"I give my old {clothes} to charity."},{"w":"noise","vi":"tiếng ồn","ex":"There is too much {noise} in the city."},{"w":"exchange","vi":"trao đổi","ex":"I {exchange} my clothes with my brother."},{"w":"give something to charity","vi":"quyên góp cho hội từ thiện","ex":"I often {give my old clothes to charity}."},{"w":"throw away","vi":"vứt đi","ex":"Don't {throw away} plastic bags."},{"w":"instead of","vi":"thay vì","ex":"I give my old books to poor children {instead of} throwing them away."}]},{"type":"g","title":"First conditional","vi":"Câu điều kiện loại 1","notes":["Diễn tả điều có thể xảy ra trong tương lai: If + S + V (hiện tại đơn), S + will / won't + V.","If it rains, I will stay at home. · If you don't study hard, you won't get good marks. · Lan won't have a new bike if she doesn't study well."],"items":[{"t":"gap","q":"If it ___, I will stay at home. (rain)","a":["rains"]},{"t":"gap","q":"If you don't study hard, you ___ good marks. (not get)","a":["won't get","will not get"]},{"t":"gap","q":"If we hurry, we ___ to catch the bus. (manage)","a":["will manage","'ll manage"]},{"t":"gap","q":"Lan won't have a new bike if she ___ well. (not study)","a":["doesn't study","does not study"]},{"t":"gap","q":"If we recycle more, we ___ the environment. (help)","a":["will help"]},{"t":"mc","q":"If you ___ plastic bottles, you will help the environment.","o":["reuse","reused","will reuse","reusing"],"a":["reuse"]},{"t":"mc","q":"If it is sunny tomorrow, we ___ on a picnic.","o":["will go","go","went","goes"],"a":["will go"]},{"t":"mc","q":"If he ___ up early, he will miss the bus.","o":["doesn't get","won't get","didn't get","not get"],"a":["doesn't get"]},{"t":"mc","q":"We ___ more trees if we have time.","o":["will plant","plant","planted","plants"],"a":["will plant"]}]},{"type":"g","title":"Articles: a / an / the","vi":"Mạo từ","notes":["a / an = \"một\": dùng khi nói về một thứ chưa xác định hoặc nhắc đến lần đầu. a + phụ âm (a book, a dog); an + nguyên âm u, e, o, a, i (an apple, an egg, an orange).","the: dùng cho đối tượng đã xác định, người nói và người nghe đều biết (Close the door.); vật duy nhất (the Sun, the Moon, the Earth); khi nhắc lại lần thứ hai (He sees a cat. The cat is cute.)."],"items":[{"t":"gap","q":"I have ___ new pen.","a":["a"]},{"t":"gap","q":"She has ___ apple.","a":["an"]},{"t":"gap","q":"___ Sun is hot.","a":["The"]},{"t":"gap","q":"He sees a cat. ___ cat is cute.","a":["The"]},{"t":"gap","q":"I eat ___ egg every morning.","a":["an"]},{"t":"mc","q":"Close ___ door, please.","o":["the","a","an","x"],"a":["the"]},{"t":"mc","q":"My mother is ___ teacher.","o":["a","an","the","x"],"a":["a"]},{"t":"mc","q":"I like to see ___ Moon at night.","o":["the","a","an","x"],"a":["the"]},{"t":"mc","q":"There is ___ orange on the table.","o":["an","a","the","x"],"a":["an"]}]}]},{"g":6,"u":12,"title":"Robots","vi":"Rô-bốt","lessons":[{"type":"v","title":"Robots – Các loại rô-bốt","words":[{"w":"home robot","vi":"rô-bốt làm việc nhà","ex":"A {home robot} can clean the house."},{"w":"teacher robot","vi":"rô-bốt giáo viên","ex":"The {teacher robot} can teach English."},{"w":"teach","vi":"dạy","ex":"Robots will {teach} children in the future."},{"w":"worker robot","vi":"rô-bốt công nhân","ex":"A {worker robot} can build houses."},{"w":"build houses","vi":"xây nhà","ex":"Worker robots can {build houses}."},{"w":"move heavy things","vi":"di chuyển đồ vật nặng","ex":"Robots can {move heavy things} easily."},{"w":"doctor robot","vi":"rô-bốt bác sĩ","ex":"A {doctor robot} can look after sick people."},{"w":"look after sick people","vi":"chăm sóc người bệnh","ex":"Doctor robots will {look after sick people}."},{"w":"space robot","vi":"rô-bốt không gian","ex":"A {space robot} can build space stations."},{"w":"build space stations","vi":"xây trạm không gian","ex":"Space robots help {build space stations}."},{"w":"useful","vi":"có ích","ex":"Robots are very {useful}."},{"w":"smart","vi":"thông minh","ex":"My robot is very {smart}."},{"w":"understand our feelings","vi":"hiểu cảm xúc của chúng ta","ex":"Robots can't {understand our feelings}."},{"w":"strong","vi":"mạnh","ex":"Worker robots are very {strong}."}]},{"type":"v","title":"Daily activities – Hoạt động hằng ngày","words":[{"w":"do household chores","vi":"làm công việc nhà","ex":"Robots will {do household chores} for us."},{"w":"cook meals","vi":"nấu các bữa ăn","ex":"Our robot can {cook meals}."},{"w":"do the dishes","vi":"rửa chén bát","ex":"I {do the dishes} after dinner."},{"w":"do the washing","vi":"giặt quần áo","ex":"The robot will {do the washing} on Monday."},{"w":"iron the clothes","vi":"ủi quần áo","ex":"Can your robot {iron the clothes}?"},{"w":"repair a broken machine","vi":"sửa chữa máy móc bị hỏng","ex":"This robot can {repair a broken machine}."},{"w":"put toys away","vi":"cất đồ chơi","ex":"{Put toys away} after you play."},{"w":"clean the house","vi":"lau dọn nhà cửa","ex":"We {clean the house} at the weekend."},{"w":"pick fruit","vi":"hái trái cây","ex":"Robots can {pick fruit} on farms."},{"w":"water plants","vi":"tưới cây","ex":"Please {water plants} in the garden."},{"w":"work as a guard","vi":"làm bảo vệ","ex":"The robot can {work as a guard} at night."},{"w":"be interested in","vi":"thích, quan tâm đến","ex":"I {am interested in} robots."}]},{"type":"g","title":"Superlative adjectives","vi":"So sánh nhất (tính từ ngắn)","notes":["Công thức: the + adj ngắn + -est: He is the tallest in his class. This dog is the smallest of the three dogs.","Tận cùng -e chỉ thêm -st: large → the largest. Một nguyên âm + một phụ âm cuối → gấp đôi phụ âm: big → the biggest.","Bất quy tắc: good → the best, bad → the worst, far → the farthest/furthest, many/much → the most, little → the least."],"items":[{"t":"gap","q":"Mount Everest is the ___ mountain in the world. (high)","a":["highest"]},{"t":"gap","q":"This is the ___ day of the year so far. (cold)","a":["coldest"]},{"t":"gap","q":"This is the ___ building in our city. (big)","a":["biggest"]},{"t":"gap","q":"Tom is the ___ runner in his team. (fast)","a":["fastest"]},{"t":"gap","q":"He is the ___ in his class. (tall)","a":["tallest"]},{"t":"gap","q":"An elephant is the ___ animal here. (large)","a":["largest"]},{"t":"gap","q":"This is the ___ film I have ever seen. (bad)","a":["worst"]},{"t":"mc","q":"This is ___ book in my collection.","o":["the best","the good","the better","best"],"a":["the best"]},{"t":"mc","q":"She is ___ student in my class.","o":["the hardest","the hard","the harder","hardest"],"a":["the hardest"]},{"t":"mc","q":"That is ___ cat of all.","o":["the cutest","the cute","the cuter","cutest"],"a":["the cutest"]},{"t":"mc","q":"He runs ___ than his brother.","o":["faster","fast","the fastest","fastest"],"a":["faster"]},{"t":"mc","q":"This exercise is ___ in the test.","o":["the easiest","the easy","the easier","easiest"],"a":["the easiest"]}]}]}];